  dg_list_none: ["No token has been issued.", "No se ha emitido ningún token.", "Es wurde noch kein Token ausgestellt.", "Aucun jeton n'a été émis.", "Nessun token è stato emesso.", "発行されたトークンはありません。", "尚未签发任何令牌。"],
  dg_status_active: ["active", "activo", "aktiv", "actif", "attivo", "有効", "有效"],
