  dg_no_label: ["(no note)", "(sin nota)", "(ohne Notiz)", "(sans note)", "(senza nota)", "（メモなし）", "（无备注）"],
  dg_revoke: ["Revoke", "Revocar", "Widerrufen", "Révoquer", "Revoca", "取り消す", "撤销"],
  dg_revoke_q: ["Revoke the token {0}? Whoever holds it loses access at once.", "¿Revocar el token {0}? Quien lo tenga pierde el acceso al instante.", "Token {0} widerrufen? Wer es besitzt, verliert sofort den Zugriff.", "Révoquer le jeton {0} ? Celui qui le détient perd l'accès aussitôt.", "Revocare il token {0}? Chi lo possiede perde subito l'accesso.", "トークン {0} を取り消しますか？持っている人は直ちにアクセスできなくなります。", "撤销令牌 {0}？持有者会立刻失去访问权限。"],
  dg_revoked_ok: ["The token was revoked.", "El token fue revocado.", "Das Token wurde widerrufen.", "Le jeton a été révoqué.", "Il token è stato revocato.", "トークンを取り消しました。", "令牌已撤销。"],
  dg_load_failed: ["The list of tokens could not be read.", "No se pudo leer la lista de tokens.", "Die Liste der Tokens konnte nicht gelesen werden.", "La liste des jetons n'a pas pu être lue.", "Non è stato possibile leggere l'elenco dei token.", "トークンの一覧を読み込めませんでした。", "无法读取令牌列表。"],
  dg_err_elevation_required: ["It needs your password or code again, and it was not given.", "Hace falta tu contraseña o código de nuevo y no se dio.", "Passwort oder Code werden erneut benötigt und wurden nicht eingegeben.", "Votre mot de passe ou code est de nouveau nécessaire et n'a pas été fourni.", "Serve di nuovo la tua password o il tuo codice e non è stato fornito.", "パスワードまたはコードの再入力が必要ですが、入力されませんでした。", "需要再次输入密码或验证码，但未提供。"],
  dg_err_invalid_request: ["The request is not valid: choose between 1 and 16 nodes and a duration from 5 minutes to 24 hours.", "La petición no es válida: elige entre 1 y 16 nodos y una duración de 5 minutos a 24 horas.", "Die Anfrage ist ungültig: Wählen Sie 1 bis 16 Knoten und eine Dauer von 5 Minuten bis 24 Stunden.", "La demande n'est pas valide : choisissez de 1 à 16 nœuds et une durée de 5 minutes à 24 heures.", "La richiesta non è valida: scegli da 1 a 16 nodi e una durata da 5 minuti a 24 ore.", "リクエストが不正です。1〜16個のノードと、5分〜24時間の有効期間を選んでください。", "请求无效：请选择 1 至 16 个节点，以及 5 分钟至 24 小时的有效期。"],
  dg_err_unknown_node: ["One of the nodes has not reported to the server.", "Uno de los nodos no ha informado al servidor.", "Einer der Knoten hat sich beim Server noch nicht gemeldet.", "L'un des nœuds n'a pas rapporté au serveur.", "Uno dei nodi non ha riferito al server.", "いずれかのノードがサーバーに報告していません。", "其中一个节点尚未向服务器上报。"],
  dg_err_too_many_tokens: ["There are too many active tokens: revoke some before issuing another.", "Hay demasiados tokens activos: revoca alguno antes de emitir otro.", "Es gibt zu viele aktive Tokens: Widerrufen Sie einige, bevor Sie ein weiteres ausstellen.", "Il y a trop de jetons actifs : révoquez-en avant d'en émettre un autre.", "Ci sono troppi token attivi: revocane qualcuno prima di emetterne un altro.", "有効なトークンが多すぎます。新しく発行する前にいくつか取り消してください。", "有效令牌过多：请先撤销一些再签发新的。"],
